import sys

def main():
    import sys
    import collections

    input = sys.stdin.read().split()
    n = int(input[0])
    m = int(input[1])
    grid = [input[i + 2] for i in range(n)]

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rootX = find(x)
        rootY = find(y)
        if rootX != rootY:
            if rank[rootX] > rank[rootY]:
                parent[rootY] = rootX
            elif rank[rootX] < rank[rootY]:
                parent[rootX] = rootY
            else:
                parent[rootY] = rootX
                rank[rootX] += 1

    def get_id(r, c):
        return r * m + c

    parent = list(range(n * m))
    rank = [0] * (n * m)

    for r in range(n):
        for c in range(m):
            if grid[r][c] == 'U':
                union(get_id(r, c), get_id(r + 1, c))
            elif grid[r][c] == 'L':
                union(get_id(r, c), get_id(r, c + 1))

    components = collections.defaultdict(set)
    for r in range(n):
        for c in range(m):
            root = find(get_id(r, c))
            components[root].add((r, c))

    photos = set()

    for r in range(n):
        for c in range(m):
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m:
                    new_photos = set()
                    for component in components.values():
                        if (r, c) in component and (nr, nc) in component:
                            new_component = component - {(r, c), (nr, nc)}
                            if new_component:
                                new_root = find(get_id(*new_component.pop()))
                                new_photos.add(new_root)
                    for p in new_photos:
                        photos.add((find(get_id(r, c)), p))
                    break

    print(len(photos))

if __name__ == "__main__":
    main()
